package com.mustafafaraz.locateme
import android.os.Bundle import android.widget.ImageView import android.widget.TextView import androidx.appcompat.app.AppCompatActivity import androidx.recyclerview.widget.LinearLayoutManager import androidx.recyclerview.widget.RecyclerView import com.mustafafaraz.locateme.adapter.ChatListAdapter import com.mustafafaraz.locateme.data.model.Chat
class ChatList : AppCompatActivity() {
private lateinit var backButton: ImageView private lateinit var titleText: TextView private lateinit var chatsRecyclerView: RecyclerView private lateinit var adapter: ChatListAdapter private lateinit var chatsList: MutableList<Chat>
override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState) setContentView(R.layout.activity_chat_list)
backButton = findViewById(R.id.back_button) titleText = findViewById(R.id.title_text) chatsRecyclerView = findViewById(R.id.chats_recyclerview)
backButton.setOnClickListener { finish() }
// Initialize sample chats chatsList = mutableListOf( Chat( id = "1", userName = "John Doe", userEmail = "john@example.com", lastMessage = "Did you find my backpack?", timestamp = "10:30 AM", unreadCount = 2, userAvatar = R.drawable.ic_person ), Chat( id = "2", userName = "Sarah Johnson", userEmail = "sarah@example.com", lastMessage = "Thanks for finding my keys!", timestamp = "Yesterday", unreadCount = 0, userAvatar = R.drawable.ic_person ), Chat( id = "3", userName = "Mike Chen", userEmail = "mike@example.com", lastMessage = "When can we meet?", timestamp = "2:45 PM", unreadCount = 1, userAvatar = R.drawable.ic_person ), Chat( id = "4", userName = "Emma Wilson", userEmail = "emma@example.com", lastMessage = "Great! See you tomorrow", timestamp = "Yesterday", unreadCount = 0, userAvatar = R.drawable.ic_person ), Chat( id = "5", userName = "Alex Thompson", userEmail = "alex@example.com", lastMessage = "I found something near the library", timestamp = "3 days ago", unreadCount = 0, userAvatar = R.drawable.ic_person ) )
setupRecyclerView() }
private fun setupRecyclerView() { chatsRecyclerView.layoutManager = LinearLayoutManager(this) adapter = ChatListAdapter(this, chatsList) chatsRecyclerView.adapter = adapter } }

package com.mustafafaraz.locateme

import android.content.Intent
import android.os.Bundle
import android.util.Log
import android.view.View
import android.widget.ImageView
import android.widget.LinearLayout
import android.widget.ProgressBar
import android.widget.TextView
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.mustafafaraz.locateme.adapter.ChatListAdapter
import com.mustafafaraz.locateme.data.api.RetrofitClient
import com.mustafafaraz.locateme.data.model.Chat
import com.mustafafaraz.locateme.utils.TokenManager
import kotlinx.coroutines.launch

class ChatList : AppCompatActivity() {

    private lateinit var backButton: ImageView
    private lateinit var titleText: TextView
    private lateinit var chatsRecyclerView: RecyclerView
    private lateinit var emptyState: LinearLayout
    private lateinit var progressBar: ProgressBar
    private lateinit var adapter: ChatListAdapter
    private lateinit var tokenManager: TokenManager
    private val chatsList = mutableListOf<Chat>()

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_chat_list)

        tokenManager = TokenManager(this)

        initializeViews()
        setupRecyclerView()
        loadChats()
    }

    override fun onResume() {
        super.onResume()
        // Reload chats when returning from chat screen
        loadChats()
    }

    private fun initializeViews() {
        backButton = findViewById(R.id.back_button)
        titleText = findViewById(R.id.title_text)
        chatsRecyclerView = findViewById(R.id.chats_recyclerview)
        emptyState = findViewById(R.id.empty_state)
        progressBar = findViewById(R.id.progress_bar)

        backButton.setOnClickListener {
            finish()
        }
    }

    private fun setupRecyclerView() {
        adapter = ChatListAdapter(this, chatsList) { chat ->
            openChat(chat)
        }
        chatsRecyclerView.layoutManager = LinearLayoutManager(this)
        chatsRecyclerView.adapter = adapter
    }

    private fun loadChats() {
        lifecycleScope.launch {
            try {
                progressBar.visibility = View.VISIBLE
                emptyState.visibility = View.GONE
                chatsRecyclerView.visibility = View.GONE

                val token = tokenManager.getToken()
                if (token.isNullOrEmpty()) {
                    Toast.makeText(this@ChatList, "Please login", Toast.LENGTH_SHORT).show()
                    finish()
                    return@launch
                }

                val authHeader = "Bearer $token"
                val response = RetrofitClient.apiService.getUserChats(authHeader)

                progressBar.visibility = View.GONE

                if (response.isSuccessful && response.body()?.success == true) {
                    val chats = response.body()?.data ?: emptyList()

                    if (chats.isEmpty()) {
                        emptyState.visibility = View.VISIBLE
                        chatsRecyclerView.visibility = View.GONE
                    } else {
                        emptyState.visibility = View.GONE
                        chatsRecyclerView.visibility = View.VISIBLE
                        chatsList.clear()
                        chatsList.addAll(chats)
                        adapter.notifyDataSetChanged()
                    }
                } else {
                    Toast.makeText(this@ChatList, "Failed to load chats", Toast.LENGTH_SHORT).show()
                    emptyState.visibility = View.VISIBLE
                }
            } catch (e: Exception) {
                Log.e("ChatList", "Error loading chats", e)
                progressBar.visibility = View.GONE
                emptyState.visibility = View.VISIBLE
                Toast.makeText(this@ChatList, "Error: ${e.message}", Toast.LENGTH_SHORT).show()
            }
        }
    }

    private fun openChat(chat: Chat) {
        val intent = Intent(this, ChatScreen::class.java).apply {
            putExtra("chat_id", chat.id)
        }
        startActivity(intent)
    }
}

package com.mustafafaraz.locateme
import android.os.Bundle import android.widget.ImageView import androidx.appcompat.app.AppCompatActivity import androidx.recyclerview.widget.LinearLayoutManager import androidx.recyclerview.widget.RecyclerView import com.mustafafaraz.locateme.adapter.ChatMessagesAdapter import com.mustafafaraz.locateme.data.model.ChatMessage
class ChatScreen : AppCompatActivity() {
private lateinit var backButton: ImageView private lateinit var messagesRecyclerView: RecyclerView private lateinit var adapter: ChatMessagesAdapter private lateinit var messages: MutableList<ChatMessage>
override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState) setContentView(R.layout.activity_chat_screen)
backButton = findViewById(R.id.back_button) messagesRecyclerView = findViewById(R.id.messages_recyclerview)
backButton.setOnClickListener { finish() }
// Initialize sample messages messages = mutableListOf( ChatMessage("Hi, did you find my backpack?", "received", "10:30 AM"), ChatMessage("Yes, I found it near the library!", "sent", "10:32 AM"), ChatMessage("That's great! When can we meet?", "received", "10:35 AM"), ChatMessage("How about at 2 PM near the cafeteria?", "sent", "10:37 AM"), ChatMessage("Perfect! See you then", "received", "10:40 AM") )
setupRecyclerView() }
private fun setupRecyclerView() { messagesRecyclerView.layoutManager = LinearLayoutManager(this) adapter = ChatMessagesAdapter(this, messages) messagesRecyclerView.adapter = adapter } }

package com.mustafafaraz.locateme

import android.app.Activity
import android.content.Intent
import android.graphics.Bitmap
import android.net.Uri
import android.os.Bundle
import android.os.Handler
import android.os.Looper
import android.provider.MediaStore
import android.util.Base64
import android.util.Log
import android.widget.EditText
import android.widget.ImageView
import android.widget.TextView
import android.widget.Toast
import androidx.appcompat.app.AlertDialog
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.mustafafaraz.locateme.adapter.ChatMessagesAdapter
import com.mustafafaraz.locateme.data.api.RetrofitClient
import com.mustafafaraz.locateme.data.model.ChatMessage
import com.mustafafaraz.locateme.data.model.SendMessageRequest
import com.mustafafaraz.locateme.utils.TokenManager
import kotlinx.coroutines.launch
import java.io.ByteArrayOutputStream

class ChatScreen : AppCompatActivity() {

    private lateinit var tokenManager: TokenManager
    private lateinit var backButton: ImageView
    private lateinit var userName: TextView
    private lateinit var messagesRecyclerView: RecyclerView
    private lateinit var messageInput: EditText
    private lateinit var sendButton: ImageView
    private lateinit var attachImageButton: ImageView
    private lateinit var adapter: ChatMessagesAdapter

    private var chatId: Int = -1
    private var otherUserId: Int = -1
    private var currentUserId: Int = -1
    private val messages = mutableListOf<ChatMessage>()

    private val handler = Handler(Looper.getMainLooper())
    private val refreshInterval = 3000L // Refresh every 3 seconds
    private var isRefreshing = false

    companion object {
        private const val PICK_IMAGE_REQUEST = 1001
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_chat_screen)

        tokenManager = TokenManager(this)

        // Get current user ID
        lifecycleScope.launch {
            val userIdString = tokenManager.getUserId()
            currentUserId = userIdString?.toIntOrNull() ?: -1
        }

        initializeViews()

        // Get chat info from intent
        chatId = intent.getIntExtra("chat_id", -1)
        val itemId = intent.getIntExtra("item_id", -1)

        if (chatId != -1) {
            // Existing chat - load messages
            loadChatDetails()
            loadMessages()
        } else if (itemId != -1) {
            // New chat from item
            createChatFromItem(itemId)
        } else {
            Toast.makeText(this, "Invalid chat", Toast.LENGTH_SHORT).show()
            finish()
        }

        setupListeners()
    }

    private fun initializeViews() {
        backButton = findViewById(R.id.back_button)
        userName = findViewById(R.id.user_name)
        messagesRecyclerView = findViewById(R.id.messages_recyclerview)
        messageInput = findViewById(R.id.message_input)
        sendButton = findViewById(R.id.send_button)
        attachImageButton = findViewById(R.id.attach_image_button)

        setupRecyclerView()
    }

    private fun setupRecyclerView() {
        adapter = ChatMessagesAdapter(this, messages, currentUserId) { message ->
            handleMessageLongClick(message)
        }
        messagesRecyclerView.layoutManager = LinearLayoutManager(this)
        messagesRecyclerView.adapter = adapter
    }

    private fun setupListeners() {
        backButton.setOnClickListener {
            finish()
        }

        sendButton.setOnClickListener {
            sendTextMessage()
        }

        attachImageButton.setOnClickListener {
            pickImage()
        }
    }

    private fun createChatFromItem(itemId: Int) {
        lifecycleScope.launch {
            try {
                val token = tokenManager.getToken()
                if (token.isNullOrEmpty()) {
                    Toast.makeText(this@ChatScreen, "Please login", Toast.LENGTH_SHORT).show()
                    finish()
                    return@launch
                }

                val authHeader = "Bearer $token"
                val response = RetrofitClient.apiService.createChatFromItem(authHeader, itemId)

                if (response.isSuccessful && response.body()?.success == true) {
                    val chat = response.body()?.data
                    chat?.let {
                        chatId = it.id
                        otherUserId = it.otherUserId
                        userName.text = it.otherUserName
                        loadMessages()
                        startAutoRefresh()
                    }
                } else {
                    val errorMsg = response.body()?.message ?: "Failed to create chat"
                    Toast.makeText(this@ChatScreen, errorMsg, Toast.LENGTH_SHORT).show()
                    finish()
                }
            } catch (e: Exception) {
                Log.e("ChatScreen", "Error creating chat", e)
                Toast.makeText(this@ChatScreen, "Error: ${e.message}", Toast.LENGTH_SHORT).show()
                finish()
            }
        }
    }

    private fun loadChatDetails() {
        lifecycleScope.launch {
            try {
                val token = tokenManager.getToken()
                if (token.isNullOrEmpty()) return@launch

                val authHeader = "Bearer $token"
                val response = RetrofitClient.apiService.getChatById(authHeader, chatId)

                if (response.isSuccessful && response.body()?.success == true) {
                    val chat = response.body()?.data
                    chat?.let {
                        otherUserId = it.otherUserId
                        userName.text = it.otherUserName
                        startAutoRefresh()
                    }
                }
            } catch (e: Exception) {
                Log.e("ChatScreen", "Error loading chat details", e)
            }
        }
    }

    private fun loadMessages() {
        lifecycleScope.launch {
            try {
                val token = tokenManager.getToken()
                if (token.isNullOrEmpty()) return@launch

                val authHeader = "Bearer $token"
                val response = RetrofitClient.apiService.getChatMessages(authHeader, chatId)

                if (response.isSuccessful && response.body()?.success == true) {
                    val newMessages = response.body()?.data ?: emptyList()

                    if (newMessages.isNotEmpty()) {
                        adapter.updateMessages(newMessages)
                        scrollToBottom()

                        // Mark messages as read
                        markMessagesAsRead()
                    }
                }
            } catch (e: Exception) {
                Log.e("ChatScreen", "Error loading messages", e)
            }
        }
    }

    private fun sendTextMessage() {
        val messageText = messageInput.text.toString().trim()
        if (messageText.isEmpty()) return

        lifecycleScope.launch {
            try {
                val token = tokenManager.getToken()
                if (token.isNullOrEmpty()) return@launch

                val authHeader = "Bearer $token"
                val request = SendMessageRequest(
                    chatId = chatId,
                    type = "TEXT",
                    content = messageText
                )

                val response = RetrofitClient.apiService.sendMessage(authHeader, request)

                if (response.isSuccessful && response.body()?.success == true) {
                    val sentMessage = response.body()?.data
                    sentMessage?.let {
                        adapter.addMessage(it)
                        scrollToBottom()
                        messageInput.text.clear()
                    }
                } else {
                    Toast.makeText(this@ChatScreen, "Failed to send message", Toast.LENGTH_SHORT).show()
                }
            } catch (e: Exception) {
                Log.e("ChatScreen", "Error sending message", e)
                Toast.makeText(this@ChatScreen, "Error: ${e.message}", Toast.LENGTH_SHORT).show()
            }
        }
    }

    private fun pickImage() {
        val intent = Intent(Intent.ACTION_PICK, MediaStore.Images.Media.EXTERNAL_CONTENT_URI)
        startActivityForResult(intent, PICK_IMAGE_REQUEST)
    }

    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
        super.onActivityResult(requestCode, resultCode, data)

        if (requestCode == PICK_IMAGE_REQUEST && resultCode == Activity.RESULT_OK && data != null) {
            val imageUri: Uri? = data.data
            imageUri?.let {
                sendImageMessage(it)
            }
        }
    }

    private fun sendImageMessage(imageUri: Uri) {
        lifecycleScope.launch {
            try {
                val token = tokenManager.getToken()
                if (token.isNullOrEmpty()) return@launch

                // Convert image to base64
                val bitmap = MediaStore.Images.Media.getBitmap(contentResolver, imageUri)
                val resizedBitmap = resizeBitmap(bitmap, 1024, 1024)
                val base64Image = bitmapToBase64(resizedBitmap)

                val authHeader = "Bearer $token"
                val request = SendMessageRequest(
                    chatId = chatId,
                    type = "IMAGE",
                    messageImage = base64Image
                )

                val response = RetrofitClient.apiService.sendMessage(authHeader, request)

                if (response.isSuccessful && response.body()?.success == true) {
                    val sentMessage = response.body()?.data
                    sentMessage?.let {
                        adapter.addMessage(it)
                        scrollToBottom()
                    }
                } else {
                    Toast.makeText(this@ChatScreen, "Failed to send image", Toast.LENGTH_SHORT).show()
                }
            } catch (e: Exception) {
                Log.e("ChatScreen", "Error sending image", e)
                Toast.makeText(this@ChatScreen, "Error: ${e.message}", Toast.LENGTH_SHORT).show()
            }
        }
    }

    private fun handleMessageLongClick(message: ChatMessage) {
        // Check if message is within 5 minutes
        val messageTime = parseTimestamp(message.createdAt)
        val currentTime = System.currentTimeMillis()
        val timeDiff = (currentTime - messageTime) / 1000 / 60 // minutes

        if (timeDiff > 5) {
            Toast.makeText(this, "Messages can only be deleted within 5 minutes", Toast.LENGTH_SHORT).show()
            return
        }

        // Show confirmation dialog
        AlertDialog.Builder(this)
            .setTitle("Delete Message")
            .setMessage("Are you sure you want to delete this message?")
            .setPositiveButton("Delete") { _, _ ->
                deleteMessage(message)
            }
            .setNegativeButton("Cancel", null)
            .show()
    }

    private fun deleteMessage(message: ChatMessage) {
        lifecycleScope.launch {
            try {
                val token = tokenManager.getToken()
                if (token.isNullOrEmpty()) return@launch

                val authHeader = "Bearer $token"
                val response = RetrofitClient.apiService.deleteMessage(authHeader, message.id)

                if (response.isSuccessful && response.body()?.success == true) {
                    adapter.removeMessage(message.id)
                    Toast.makeText(this@ChatScreen, "Message deleted", Toast.LENGTH_SHORT).show()
                } else {
                    val errorMsg = response.body()?.message ?: "Failed to delete message"
                    Toast.makeText(this@ChatScreen, errorMsg, Toast.LENGTH_SHORT).show()
                }
            } catch (e: Exception) {
                Log.e("ChatScreen", "Error deleting message", e)
                Toast.makeText(this@ChatScreen, "Error: ${e.message}", Toast.LENGTH_SHORT).show()
            }
        }
    }

    private fun markMessagesAsRead() {
        lifecycleScope.launch {
            try {
                val token = tokenManager.getToken()
                if (token.isNullOrEmpty()) return@launch

                val authHeader = "Bearer $token"
                RetrofitClient.apiService.markMessagesAsRead(authHeader, chatId)
            } catch (e: Exception) {
                Log.e("ChatScreen", "Error marking messages as read", e)
            }
        }
    }

    private fun startAutoRefresh() {
        handler.postDelayed(object : Runnable {
            override fun run() {
                if (!isRefreshing) {
                    isRefreshing = true
                    refreshMessages()
                }
                handler.postDelayed(this, refreshInterval)
            }
        }, refreshInterval)
    }

    private fun refreshMessages() {
        lifecycleScope.launch {
            try {
                val token = tokenManager.getToken()
                if (token.isNullOrEmpty()) {
                    isRefreshing = false
                    return@launch
                }

                val authHeader = "Bearer $token"
                val response = RetrofitClient.apiService.getChatMessages(authHeader, chatId)

                if (response.isSuccessful && response.body()?.success == true) {
                    val newMessages = response.body()?.data ?: emptyList()

                    // Only update if there are new messages
                    if (newMessages.size > messages.size) {
                        val wasAtBottom = isAtBottom()
                        adapter.updateMessages(newMessages)

                        if (wasAtBottom) {
                            scrollToBottom()
                        }

                        markMessagesAsRead()
                    }
                }
            } catch (e: Exception) {
                Log.e("ChatScreen", "Error refreshing messages", e)
            } finally {
                isRefreshing = false
            }
        }
    }

    private fun scrollToBottom() {
        if (messages.isNotEmpty()) {
            messagesRecyclerView.smoothScrollToPosition(messages.size - 1)
        }
    }

    private fun isAtBottom(): Boolean {
        val layoutManager = messagesRecyclerView.layoutManager as LinearLayoutManager
        val lastVisiblePosition = layoutManager.findLastCompletelyVisibleItemPosition()
        return lastVisiblePosition >= messages.size - 1
    }

    private fun parseTimestamp(timestamp: String): Long {
        return try {
            val format = java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'", java.util.Locale.US)
            format.timeZone = java.util.TimeZone.getTimeZone("UTC")
            format.parse(timestamp)?.time ?: System.currentTimeMillis()
        } catch (e: Exception) {
            System.currentTimeMillis()
        }
    }

    private fun resizeBitmap(bitmap: Bitmap, maxWidth: Int, maxHeight: Int): Bitmap {
        val width = bitmap.width
        val height = bitmap.height

        val ratioBitmap = width.toFloat() / height.toFloat()
        val ratioMax = maxWidth.toFloat() / maxHeight.toFloat()

        var finalWidth = maxWidth
        var finalHeight = maxHeight

        if (ratioMax > ratioBitmap) {
            finalWidth = (maxHeight.toFloat() * ratioBitmap).toInt()
        } else {
            finalHeight = (maxWidth.toFloat() / ratioBitmap).toInt()
        }

        return Bitmap.createScaledBitmap(bitmap, finalWidth, finalHeight, true)
    }

    private fun bitmapToBase64(bitmap: Bitmap): String {
        val byteArrayOutputStream = ByteArrayOutputStream()
        bitmap.compress(Bitmap.CompressFormat.JPEG, 80, byteArrayOutputStream)
        val byteArray = byteArrayOutputStream.toByteArray()
        return Base64.encodeToString(byteArray, Base64.NO_WRAP)
    }

    override fun onDestroy() {
        super.onDestroy()
        handler.removeCallbacksAndMessages(null)
    }
}

package com.mustafafaraz.locateme

import android.content.Intent
import android.os.Bundle
import android.util.Log
import android.view.View
import android.widget.ImageView
import android.widget.LinearLayout
import android.widget.ProgressBar
import android.widget.TextView
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.bumptech.glide.Glide
import com.mustafafaraz.locateme.adapter.ImageGalleryAdapter
import com.mustafafaraz.locateme.data.api.RetrofitClient
import com.mustafafaraz.locateme.data.model.Item
import com.mustafafaraz.locateme.data.model.SaveItemRequest
import com.mustafafaraz.locateme.utils.TokenManager
import kotlinx.coroutines.launch

class ItemDetails : AppCompatActivity() {

    private lateinit var tokenManager: TokenManager
    private lateinit var mainImageView: ImageView
    private lateinit var imagesRecyclerView: RecyclerView
    private lateinit var progressBar: ProgressBar
    private lateinit var bookmarkButton: ImageView
    private var currentItem: Item? = null

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_item_details)

        tokenManager = TokenManager(this)

        // Initialize views
        initializeViews()

        // Get item ID from intent
        val itemId = intent.getIntExtra("item_id", -1)
        if (itemId != -1) {
            loadItemDetails(itemId)
        } else {
            Toast.makeText(this, "Invalid item", Toast.LENGTH_SHORT).show()
            finish()
        }
    }

    private fun initializeViews() {
        mainImageView = findViewById(R.id.item_image)
        imagesRecyclerView = findViewById(R.id.images_recycler_view)
        progressBar = findViewById(R.id.progress_bar)

        findViewById<ImageView>(R.id.back_button).setOnClickListener {
            finish()
        }
    }

    private fun loadItemDetails(itemId: Int) {
        lifecycleScope.launch {
            try {
                progressBar.visibility = View.VISIBLE

                val token = tokenManager.getToken()
                if (token.isNullOrEmpty()) {
                    Toast.makeText(this@ItemDetails, "Please login", Toast.LENGTH_SHORT).show()
                    finish()
                    return@launch
                }

                val authHeader = "Bearer $token"
                val response = RetrofitClient.apiService.getItemById(authHeader, itemId)

                progressBar.visibility = View.GONE

                if (response.isSuccessful && response.body()?.success == true) {
                    currentItem = response.body()?.data
                    currentItem?.let { displayItemDetails(it) }
                } else {
                    Toast.makeText(this@ItemDetails, "Failed to load item details", Toast.LENGTH_SHORT).show()
                    finish()
                }
            } catch (e: Exception) {
                Log.e("ItemDetails", "Error loading item", e)
                progressBar.visibility = View.GONE
                Toast.makeText(this@ItemDetails, "Network error: ${e.message}", Toast.LENGTH_SHORT).show()
                finish()
            }
        }
    }

    private fun displayItemDetails(item: Item) {
        // Set badge
        findViewById<TextView>(R.id.item_badge).apply {
            text = item.type
            setBackgroundResource(
                if (item.type == "LOST") R.drawable.lost_badge else R.drawable.found_badge
            )
        }

        // Set basic info
        findViewById<TextView>(R.id.item_title).text = item.title
        findViewById<TextView>(R.id.item_description).text = item.description
        findViewById<TextView>(R.id.item_location).text = item.location
        findViewById<TextView>(R.id.item_time).text = formatTime(item.createdAt)
        findViewById<TextView>(R.id.item_person).text = item.userName

        // Set reporter details
        findViewById<TextView>(R.id.reporter_full_name).text = item.userName
        findViewById<TextView>(R.id.reporter_student_id).text = item.userStudentId ?: "N/A"
        findViewById<TextView>(R.id.reporter_department).text = item.userDepartment ?: "N/A"
        findViewById<TextView>(R.id.reporter_batch).text = item.userBatch ?: "N/A"
        findViewById<TextView>(R.id.reporter_section).text = item.userSection ?: "N/A"

        // Load images
        setupImageGallery(item.imageUrls)

        // Setup action buttons
        setupActionButtons(item)
    }

    private fun setupImageGallery(imageUrls: List<String>) {
        if (imageUrls.isEmpty()) {
            mainImageView.setImageResource(R.drawable.item_placeholder)
            imagesRecyclerView.visibility = View.GONE
            return
        }

        // Load first image in main view
        Glide.with(this)
            .load(imageUrls[0])
            .placeholder(R.drawable.item_placeholder)
            .error(R.drawable.item_placeholder)
            .centerCrop()
            .into(mainImageView)

        // Setup image gallery if multiple images
        if (imageUrls.size > 1) {
            imagesRecyclerView.visibility = View.VISIBLE
            val adapter = ImageGalleryAdapter(imageUrls) { imageUrl ->
                // When thumbnail clicked, load in main view
                Glide.with(this)
                    .load(imageUrl)
                    .placeholder(R.drawable.item_placeholder)
                    .error(R.drawable.item_placeholder)
                    .centerCrop()
                    .into(mainImageView)
            }
            imagesRecyclerView.layoutManager = LinearLayoutManager(this, LinearLayoutManager.HORIZONTAL, false)
            imagesRecyclerView.adapter = adapter
        } else {
            imagesRecyclerView.visibility = View.GONE
        }
    }

    private fun setupActionButtons(item: Item) {
        // Message button
        findViewById<LinearLayout>(R.id.message_button).setOnClickListener {
            Toast.makeText(this, "Chat feature coming soon", Toast.LENGTH_SHORT).show()
            // TODO: Navigate to chat with this user
        }

        // Email button
        findViewById<LinearLayout>(R.id.email_button).setOnClickListener {
            val intent = Intent(Intent.ACTION_SEND).apply {
                type = "message/rfc822"
                putExtra(Intent.EXTRA_EMAIL, arrayOf(item.userEmail))
                putExtra(Intent.EXTRA_SUBJECT, "Regarding: ${item.title}")
            }
            try {
                startActivity(Intent.createChooser(intent, "Send Email"))
            } catch (e: Exception) {
                Toast.makeText(this, "No email app found", Toast.LENGTH_SHORT).show()
            }
        }

        // Favorite button
        findViewById<ImageView>(R.id.favorite_button).setOnClickListener {
            Toast.makeText(this, "Favorite feature coming soon", Toast.LENGTH_SHORT).show()
        }

        // Share button
        findViewById<ImageView>(R.id.share_button).setOnClickListener {
            val shareIntent = Intent(Intent.ACTION_SEND).apply {
                type = "text/plain"
                putExtra(Intent.EXTRA_TEXT, "${item.type}: ${item.title}\n${item.description}\nLocation: ${item.location}")
            }
            startActivity(Intent.createChooser(shareIntent, "Share Item"))
        }

        // Bookmark button - Save/Unsave functionality
        bookmarkButton = findViewById(R.id.bookmark_button)
        updateBookmarkIcon(item.isSaved)

        bookmarkButton.setOnClickListener {
            toggleSaveItem(item)
        }
    }

    private fun updateBookmarkIcon(isSaved: Boolean) {
        if (isSaved) {
            bookmarkButton.setImageResource(R.drawable.ic_bookmark)
        } else {
            bookmarkButton.setImageResource(R.drawable.ic_bookmark_outline)
        }
    }

    private fun toggleSaveItem(item: Item) {
        lifecycleScope.launch {
            try {
                val token = tokenManager.getToken()
                if (token.isNullOrEmpty()) {
                    Toast.makeText(this@ItemDetails, "Please login", Toast.LENGTH_SHORT).show()
                    return@launch
                }

                val authHeader = "Bearer $token"

                val response = if (item.isSaved) {
                    // Unsave item
                    RetrofitClient.apiService.unsaveItem(authHeader, item.id)
                } else {
                    // Save item
                    RetrofitClient.apiService.saveItem(authHeader, SaveItemRequest(item.id))
                }

                if (response.isSuccessful && response.body()?.success == true) {
                    // Toggle the saved state
                    item.isSaved = !item.isSaved
                    currentItem = item
                    updateBookmarkIcon(item.isSaved)

                    val message = if (item.isSaved) "Item saved" else "Item unsaved"
                    Toast.makeText(this@ItemDetails, message, Toast.LENGTH_SHORT).show()
                } else {
                    val errorMessage = response.body()?.message ?: "Operation failed"
                    Toast.makeText(this@ItemDetails, errorMessage, Toast.LENGTH_SHORT).show()
                }
            } catch (e: Exception) {
                Log.e("ItemDetails", "Error toggling save", e)
                Toast.makeText(this@ItemDetails, "Error: ${e.message}", Toast.LENGTH_SHORT).show()
            }
        }
    }

    private fun formatTime(timestamp: String): String {
        return try {
            timestamp.substringBefore("T")
        } catch (e: Exception) {
            timestamp
        }
    }
}

package com.mustafafaraz.locateme

import android.content.Intent
import android.os.Bundle
import android.util.Log
import android.view.View
import android.widget.ImageView
import android.widget.LinearLayout
import android.widget.ProgressBar
import android.widget.TextView
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import androidx.recyclerview.widget.LinearLayoutManager
import androidx.recyclerview.widget.RecyclerView
import com.bumptech.glide.Glide
import com.mustafafaraz.locateme.adapter.ImageGalleryAdapter
import com.mustafafaraz.locateme.data.api.RetrofitClient
import com.mustafafaraz.locateme.data.model.Item
import com.mustafafaraz.locateme.data.model.SaveItemRequest
import com.mustafafaraz.locateme.utils.TokenManager
import kotlinx.coroutines.launch

class ItemDetails : AppCompatActivity() {

    private lateinit var tokenManager: TokenManager
    private lateinit var mainImageView: ImageView
    private lateinit var imagesRecyclerView: RecyclerView
    private lateinit var progressBar: ProgressBar
    private lateinit var bookmarkButton: ImageView
    private var currentItem: Item? = null

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_item_details)

        tokenManager = TokenManager(this)

        // Initialize views
        initializeViews()

        // Get item ID from intent
        val itemId = intent.getIntExtra("item_id", -1)
        if (itemId != -1) {
            loadItemDetails(itemId)
        } else {
            Toast.makeText(this, "Invalid item", Toast.LENGTH_SHORT).show()
            finish()
        }
    }

    private fun initializeViews() {
        mainImageView = findViewById(R.id.item_image)
        imagesRecyclerView = findViewById(R.id.images_recycler_view)
        progressBar = findViewById(R.id.progress_bar)

        findViewById<ImageView>(R.id.back_button).setOnClickListener {
            finish()
        }
    }

    private fun loadItemDetails(itemId: Int) {
        lifecycleScope.launch {
            try {
                progressBar.visibility = View.VISIBLE

                val token = tokenManager.getToken()
                if (token.isNullOrEmpty()) {
                    Toast.makeText(this@ItemDetails, "Please login", Toast.LENGTH_SHORT).show()
                    finish()
                    return@launch
                }

                val authHeader = "Bearer $token"
                val response = RetrofitClient.apiService.getItemById(authHeader, itemId)

                progressBar.visibility = View.GONE

                if (response.isSuccessful && response.body()?.success == true) {
                    currentItem = response.body()?.data
                    currentItem?.let { displayItemDetails(it) }
                } else {
                    Toast.makeText(this@ItemDetails, "Failed to load item details", Toast.LENGTH_SHORT).show()
                    finish()
                }
            } catch (e: Exception) {
                Log.e("ItemDetails", "Error loading item", e)
                progressBar.visibility = View.GONE
                Toast.makeText(this@ItemDetails, "Network error: ${e.message}", Toast.LENGTH_SHORT).show()
                finish()
            }
        }
    }

    private fun displayItemDetails(item: Item) {
        // Set badge
        findViewById<TextView>(R.id.item_badge).apply {
            text = item.type
            setBackgroundResource(
                if (item.type == "LOST") R.drawable.lost_badge else R.drawable.found_badge
            )
        }

        // Set basic info
        findViewById<TextView>(R.id.item_title).text = item.title
        findViewById<TextView>(R.id.item_description).text = item.description
        findViewById<TextView>(R.id.item_location).text = item.location
        findViewById<TextView>(R.id.item_time).text = formatTime(item.createdAt)
        findViewById<TextView>(R.id.item_person).text = item.userName

        // Set reporter details
        findViewById<TextView>(R.id.reporter_full_name).text = item.userName
        findViewById<TextView>(R.id.reporter_student_id).text = item.userStudentId ?: "N/A"
        findViewById<TextView>(R.id.reporter_department).text = item.userDepartment ?: "N/A"
        findViewById<TextView>(R.id.reporter_batch).text = item.userBatch ?: "N/A"
        findViewById<TextView>(R.id.reporter_section).text = item.userSection ?: "N/A"

        // Load images
        setupImageGallery(item.imageUrls)

        // Setup action buttons
        setupActionButtons(item)
    }

    private fun setupImageGallery(imageUrls: List<String>) {
        if (imageUrls.isEmpty()) {
            mainImageView.setImageResource(R.drawable.item_placeholder)
            imagesRecyclerView.visibility = View.GONE
            return
        }

        // Load first image in main view
        Glide.with(this)
            .load(imageUrls[0])
            .placeholder(R.drawable.item_placeholder)
            .error(R.drawable.item_placeholder)
            .centerCrop()
            .into(mainImageView)

        // Setup image gallery if multiple images
        if (imageUrls.size > 1) {
            imagesRecyclerView.visibility = View.VISIBLE
            val adapter = ImageGalleryAdapter(imageUrls) { imageUrl ->
                // When thumbnail clicked, load in main view
                Glide.with(this)
                    .load(imageUrl)
                    .placeholder(R.drawable.item_placeholder)
                    .error(R.drawable.item_placeholder)
                    .centerCrop()
                    .into(mainImageView)
            }
            imagesRecyclerView.layoutManager = LinearLayoutManager(this, LinearLayoutManager.HORIZONTAL, false)
            imagesRecyclerView.adapter = adapter
        } else {
            imagesRecyclerView.visibility = View.GONE
        }
    }

    private fun setupActionButtons(item: Item) {
        // Message button
        findViewById<LinearLayout>(R.id.message_button).setOnClickListener {
            openChatWithUser(item)
        }

        // Email button
        findViewById<LinearLayout>(R.id.email_button).setOnClickListener {
            val intent = Intent(Intent.ACTION_SEND).apply {
                type = "message/rfc822"
                putExtra(Intent.EXTRA_EMAIL, arrayOf(item.userEmail))
                putExtra(Intent.EXTRA_SUBJECT, "Regarding: ${item.title}")
            }
            try {
                startActivity(Intent.createChooser(intent, "Send Email"))
            } catch (e: Exception) {
                Toast.makeText(this, "No email app found", Toast.LENGTH_SHORT).show()
            }
        }

        // Favorite button
        findViewById<ImageView>(R.id.favorite_button).setOnClickListener {
            Toast.makeText(this, "Favorite feature coming soon", Toast.LENGTH_SHORT).show()
        }

        // Share button
        findViewById<ImageView>(R.id.share_button).setOnClickListener {
            val shareIntent = Intent(Intent.ACTION_SEND).apply {
                type = "text/plain"
                putExtra(Intent.EXTRA_TEXT, "${item.type}: ${item.title}\n${item.description}\nLocation: ${item.location}")
            }
            startActivity(Intent.createChooser(shareIntent, "Share Item"))
        }

        // Bookmark button - Save/Unsave functionality
        bookmarkButton = findViewById(R.id.bookmark_button)
        updateBookmarkIcon(item.isSaved)

        bookmarkButton.setOnClickListener {
            toggleSaveItem(item)
        }
    }

    private fun openChatWithUser(item: Item) {
        // Open chat screen with item ID to create or get existing chat
        val intent = Intent(this, ChatScreen::class.java).apply {
            putExtra("item_id", item.id)
        }
        startActivity(intent)
    }

    private fun updateBookmarkIcon(isSaved: Boolean) {
        if (isSaved) {
            bookmarkButton.setImageResource(R.drawable.ic_bookmark)
        } else {
            bookmarkButton.setImageResource(R.drawable.ic_bookmark_outline)
        }
    }

    private fun toggleSaveItem(item: Item) {
        lifecycleScope.launch {
            try {
                val token = tokenManager.getToken()
                if (token.isNullOrEmpty()) {
                    Toast.makeText(this@ItemDetails, "Please login", Toast.LENGTH_SHORT).show()
                    return@launch
                }

                val authHeader = "Bearer $token"

                val response = if (item.isSaved) {
                    // Unsave item
                    RetrofitClient.apiService.unsaveItem(authHeader, item.id)
                } else {
                    // Save item
                    RetrofitClient.apiService.saveItem(authHeader, SaveItemRequest(item.id))
                }

                if (response.isSuccessful && response.body()?.success == true) {
                    // Toggle the saved state
                    item.isSaved = !item.isSaved
                    currentItem = item
                    updateBookmarkIcon(item.isSaved)

                    val message = if (item.isSaved) "Item saved" else "Item unsaved"
                    Toast.makeText(this@ItemDetails, message, Toast.LENGTH_SHORT).show()
                } else {
                    val errorMessage = response.body()?.message ?: "Operation failed"
                    Toast.makeText(this@ItemDetails, errorMessage, Toast.LENGTH_SHORT).show()
                }
            } catch (e: Exception) {
                Log.e("ItemDetails", "Error toggling save", e)
                Toast.makeText(this@ItemDetails, "Error: ${e.message}", Toast.LENGTH_SHORT).show()
            }
        }
    }

    private fun formatTime(timestamp: String): String {
        return try {
            timestamp.substringBefore("T")
        } catch (e: Exception) {
            timestamp
        }
    }
}

package com.mustafafaraz.locateme

import android.os.Bundle
import android.view.View
import android.widget.ArrayAdapter
import android.widget.Button
import android.widget.EditText
import android.widget.ImageView
import android.widget.Spinner
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
import androidx.core.content.ContextCompat

class ReportItem : AppCompatActivity() {

    private lateinit var toggleLost: TextView
    private lateinit var toggleFound: TextView
    private lateinit var locationLabel: TextView
    private lateinit var reportButton: Button

    private lateinit var itemTitle: EditText
    private lateinit var itemCategory: Spinner
    private lateinit var itemDescription: EditText
    private lateinit var itemLocation: Spinner
    private lateinit var contactMethod: EditText
    private lateinit var contactInfo: EditText

    private var isLostItem = true

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_report_item)

        initializeViews()
        setupToggleListeners()
        setupSpinners()
        setupClickListeners()
    }

    private fun initializeViews() {
        toggleLost = findViewById(R.id.toggle_lost)
        toggleFound = findViewById(R.id.toggle_found)
        locationLabel = findViewById(R.id.location_label)
        reportButton = findViewById(R.id.report_button)

        itemTitle = findViewById(R.id.item_title)
        itemCategory = findViewById(R.id.item_category)
        itemDescription = findViewById(R.id.item_description)
        itemLocation = findViewById(R.id.item_location)
        contactMethod = findViewById(R.id.contact_method)
        contactInfo = findViewById(R.id.contact_info)
    }

    private fun setupToggleListeners() {
        toggleLost.setOnClickListener {
            if (!isLostItem) {
                switchToLost()
            }
        }

        toggleFound.setOnClickListener {
            if (isLostItem) {
                switchToFound()
            }
        }
    }

    private fun setupSpinners() {
        // Category Spinner
        val categories = arrayOf(
            "Select Category",
            "Electronics",
            "Bags",
            "Keys",
            "Clothing",
            "Books",
            "Accessories",
            "Other"
        )
        val categoryAdapter = ArrayAdapter(this, android.R.layout.simple_spinner_item, categories)
        categoryAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item)
        itemCategory.adapter = categoryAdapter

        // Location Spinner
        val locations = arrayOf(
            "Select Location",
            "Library - 1st floor",
            "Library - 2nd floor",
            "Library - 3rd floor",
            "Cafeteria",
            "Main Building",
            "Lab Block",
            "Sports Complex",
            "Parking Area",
            "Other"
        )
        val locationAdapter = ArrayAdapter(this, android.R.layout.simple_spinner_item, locations)
        locationAdapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item)
        itemLocation.adapter = locationAdapter
    }

    private fun setupClickListeners() {
        // Back button
        findViewById<ImageView>(R.id.back_button).setOnClickListener {
            finish()
        }

        // Report button
        reportButton.setOnClickListener {
            handleReportSubmit()
        }

        // Add photo button
        findViewById<View>(R.id.add_photo_button).setOnClickListener {
            // TODO: Implement photo picker
        }

        // Bottom navigation
        findViewById<View>(R.id.nav_search).setOnClickListener {
            // TODO: Navigate to search/home
        }

        findViewById<View>(R.id.nav_report).setOnClickListener {
            // Already on report screen
        }

        findViewById<View>(R.id.nav_profile).setOnClickListener {
            // TODO: Navigate to profile
        }
    }

    private fun switchToLost() {
        isLostItem = true

        // Update toggle buttons
        toggleLost.setBackgroundResource(R.drawable.selected_button_login_signup)
        toggleLost.setTextColor(ContextCompat.getColor(this, R.color.black))

        toggleFound.background = null
        toggleFound.setTextColor(ContextCompat.getColor(this, R.color.black))

        // Update text labels
        locationLabel.text = "Where did you lose it? *"
        reportButton.text = "Report Lost Item"
    }

    private fun switchToFound() {
        isLostItem = false

        // Update toggle buttons
        toggleLost.background = null
        toggleLost.setTextColor(ContextCompat.getColor(this, R.color.black))

        toggleFound.setBackgroundResource(R.drawable.selected_button_login_signup)
        toggleFound.setTextColor(ContextCompat.getColor(this, R.color.black))

        // Update text labels
        locationLabel.text = "Where did you find it? *"
        reportButton.text = "Report Found Item"
    }

    private fun handleReportSubmit() {
        val title = itemTitle.text.toString()
        val category = itemCategory.selectedItem.toString()
        val description = itemDescription.text.toString()
        val location = itemLocation.selectedItem.toString()
        val method = contactMethod.text.toString()
        val contact = contactInfo.text.toString()

        // Validation
        if (title.isEmpty()) {
            itemTitle.error = "Please enter item title"
            return
        }

        if (category == "Select Category") {
            // Show error for category
            return
        }

        if (description.isEmpty()) {
            itemDescription.error = "Please enter description"
            return
        }

        if (location == "Select Location") {
            // Show error for location
            return
        }

        if (method.isEmpty()) {
            contactMethod.error = "Please enter contact method"
            return
        }

        if (contact.isEmpty()) {
            contactInfo.error = "Please enter contact information"
            return
        }

        // TODO: Submit the report to backend/database
        val itemType = if (isLostItem) "Lost" else "Found"

        // For now, just finish the activity
        finish()
    }
}

package com.mustafafaraz.locateme.adapter

import android.content.Context
import android.view.Gravity
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.LinearLayout
import android.widget.TextView
import androidx.core.content.ContextCompat
import androidx.recyclerview.widget.RecyclerView
import com.mustafafaraz.locateme.data.model.ChatMessage
import com.mustafafaraz.locateme.R

class ChatMessagesAdapter(
    private val context: Context,
    private val messages: List<ChatMessage>
) : RecyclerView.Adapter<ChatMessagesAdapter.ChatMessageViewHolder>() {

    inner class ChatMessageViewHolder(itemView: View) :
        RecyclerView.ViewHolder(itemView) {

        private val messageText: TextView = itemView.findViewById(R.id.message_text)
        private val messageTimestamp: TextView = itemView.findViewById(R.id.message_timestamp)
        private val messageContainer: LinearLayout = itemView.findViewById(R.id.message_container)

        private val rowContainer: LinearLayout = itemView.findViewById(R.id.root_container)
        fun bind(message: ChatMessage) {
            messageText.text = message.messageText
            messageTimestamp.text = message.timestamp


            // Style based on message type (sent or received)
            if (message.type == "sent") {
                rowContainer.gravity = Gravity.END

                // Sent messages - blue background, right aligned
                messageContainer.setBackgroundResource(R.drawable.chat_sent_background)
                messageText.setTextColor(ContextCompat.getColor(context, android.R.color.white))
                messageTimestamp.setTextColor(ContextCompat.getColor(context, android.R.color.white))

                val layoutParams = messageContainer.layoutParams as LinearLayout.LayoutParams
                /*layoutParams.marginStart = 80
                layoutParams.marginEnd = 12
                messageContainer.layoutParams = layoutParams*/
            } else {
                rowContainer.gravity = Gravity.START

                // Received messages - gray background, left aligned
                messageContainer.setBackgroundResource(R.drawable.chat_received_background)
                messageText.setTextColor(ContextCompat.getColor(context, android.R.color.black))
                messageTimestamp.setTextColor(ContextCompat.getColor(context, R.color.text_color))

                /*val layoutParams = messageContainer.layoutParams as LinearLayout.LayoutParams
                layoutParams.marginStart = 12
                layoutParams.marginEnd = 80
                messageContainer.layoutParams = layoutParams*/
            }
        }
    }

    override fun onCreateViewHolder(
        parent: ViewGroup,
        viewType: Int
    ): ChatMessageViewHolder {
        val itemView = LayoutInflater.from(context)
            .inflate(R.layout.chat_message_row, parent, false)
        return ChatMessageViewHolder(itemView)
    }

    override fun onBindViewHolder(holder: ChatMessageViewHolder, position: Int) {
        holder.bind(messages[position])
    }

    override fun getItemCount(): Int = messages.size
}

package com.mustafafaraz.locateme.adapter

import android.content.Context
import android.view.Gravity
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import android.widget.ImageView
import android.widget.LinearLayout
import android.widget.TextView
import androidx.core.content.ContextCompat
import androidx.recyclerview.widget.RecyclerView
import com.bumptech.glide.Glide
import com.mustafafaraz.locateme.data.model.ChatMessage
import com.mustafafaraz.locateme.R
import com.mustafafaraz.locateme.utils.TimeFormatter

class ChatMessagesAdapter(
    private val context: Context,
    private val messages: MutableList<ChatMessage>,
    private val currentUserId: Int,
    private val onMessageLongClick: (ChatMessage) -> Unit
) : RecyclerView.Adapter<ChatMessagesAdapter.ChatMessageViewHolder>() {

    inner class ChatMessageViewHolder(itemView: View) : RecyclerView.ViewHolder(itemView) {
        private val messageText: TextView = itemView.findViewById(R.id.message_text)
        private val messageImage: ImageView = itemView.findViewById(R.id.message_image)
        private val messageTimestamp: TextView = itemView.findViewById(R.id.message_timestamp)
        private val messageContainer: LinearLayout = itemView.findViewById(R.id.message_container)
        private val rowContainer: LinearLayout = itemView.findViewById(R.id.root_container)

        fun bind(message: ChatMessage) {
            // Determine if message is sent or received
            val isSent = message.senderId == currentUserId

            // Format timestamp
            messageTimestamp.text = TimeFormatter.formatTime(message.createdAt)

            // Handle message type (TEXT or IMAGE)
            if (message.type == "TEXT") {
                messageText.visibility = View.VISIBLE
                messageImage.visibility = View.GONE
                messageText.text = message.content
            } else if (message.type == "IMAGE") {
                messageText.visibility = View.GONE
                messageImage.visibility = View.VISIBLE

                // Load image
                Glide.with(context)
                    .load(message.mediaUrl)
                    .placeholder(R.drawable.item_placeholder)
                    .error(R.drawable.item_placeholder)
                    .centerCrop()
                    .into(messageImage)
            }

            // Style based on sent/received
            if (isSent) {
                rowContainer.gravity = Gravity.END
                messageContainer.setBackgroundResource(R.drawable.chat_sent_background)
                messageText.setTextColor(ContextCompat.getColor(context, android.R.color.white))
                messageTimestamp.setTextColor(ContextCompat.getColor(context, android.R.color.white))
            } else {
                rowContainer.gravity = Gravity.START
                messageContainer.setBackgroundResource(R.drawable.chat_received_background)
                messageText.setTextColor(ContextCompat.getColor(context, android.R.color.black))
                messageTimestamp.setTextColor(ContextCompat.getColor(context, R.color.text_color))
            }

            // Long click listener for deletion (only for sent messages)
            if (isSent) {
                messageContainer.setOnLongClickListener {
                    onMessageLongClick(message)
                    true
                }
            } else {
                messageContainer.setOnLongClickListener(null)
            }
        }
    }

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): ChatMessageViewHolder {
        val itemView = LayoutInflater.from(context)
            .inflate(R.layout.chat_message_row, parent, false)
        return ChatMessageViewHolder(itemView)
    }

    override fun onBindViewHolder(holder: ChatMessageViewHolder, position: Int) {
        holder.bind(messages[position])
    }

    override fun getItemCount(): Int = messages.size

    fun addMessage(message: ChatMessage) {
        messages.add(message)
        notifyItemInserted(messages.size - 1)
    }

    fun removeMessage(messageId: Int) {
        val position = messages.indexOfFirst { it.id == messageId }
        if (position != -1) {
            messages.removeAt(position)
            notifyItemRemoved(position)
        }
    }

    fun updateMessages(newMessages: List<ChatMessage>) {
        messages.clear()
        messages.addAll(newMessages)
        notifyDataSetChanged()
    }
}

package com.mustafafaraz.locateme.data.api

import com.mustafafaraz.locateme.data.model.*
import retrofit2.Response
import retrofit2.http.*

interface ApiService {

    // Authentication Endpoints
    @POST("api/auth/signup")
    suspend fun signup(@Body request: SignupRequest): Response<ApiResponse<AuthResponse>>

    @POST("api/auth/login")
    suspend fun login(@Body request: LoginRequest): Response<ApiResponse<AuthResponse>>

    // User Profile Endpoints
    @GET("api/users/profile")
    suspend fun getProfile(
        @Header("Authorization") token: String
    ): Response<ApiResponse<User>>

    @PUT("api/users/profile")
    suspend fun updateProfile(
        @Header("Authorization") token: String,
        @Body request: UpdateProfileRequest
    ): Response<ApiResponse<User>>

    @PUT("api/users/change-password")
    suspend fun changePassword(
        @Header("Authorization") token: String,
        @Body request: ChangePasswordRequest
    ): Response<ApiResponse<Unit>>

    @HTTP(method = "DELETE", path = "api/users/account", hasBody = true)
    suspend fun deleteAccount(
        @Header("Authorization") token: String,
        @Body request: DeleteAccountRequest
    ): Response<ApiResponse<Unit>>

    // Item Endpoints
    @POST("api/items")
    suspend fun createItem(
        @Header("Authorization") token: String,
