package com.mustafafaraz.locateme.data.model

import com.google.gson.annotations.SerializedName

data class Chat(
    val id: Int,
    @SerializedName("other_user_id")
    val otherUserId: Int,
    @SerializedName("other_user_name")
    val otherUserName: String,
    @SerializedName("other_user_email")
    val otherUserEmail: String,
    @SerializedName("user_profile_pic")
    private val _userProfilePic: String?,
    @SerializedName("last_message")
    val lastMessage: String?,
    @SerializedName("last_message_type")
    val lastMessageType: String?,
    @SerializedName("last_message_time")
    val lastMessageTime: String?,
    @SerializedName("created_at")
    val createdAt: String,
    @SerializedName("last_message_at")
    val lastMessageAt: String?
) {
    val userProfilePic: String?
        get() = _userProfilePic?.replace(":5000", "")
}

data class CreateChatRequest(
    val otherUserId: Int
)

package com.mustafafaraz.locateme.data.model

import com.google.gson.annotations.SerializedName

data class ChatMessage(
    val id: Int,
    @SerializedName("chat_id")
    val chatId: Int,
    @SerializedName("sender_id")
    val senderId: Int,
    @SerializedName("receiver_id")
    val receiverId: Int,
    val type: String, // TEXT or IMAGE
    val content: String?,
    @SerializedName("media_url")
    private val _mediaUrl: String?,
    @SerializedName("is_read")
    val isRead: Boolean,
    @SerializedName("created_at")
    val createdAt: String,
    @SerializedName("sender_name")
    val senderName: String?,
    @SerializedName("sender_profile_pic")
    private val _senderProfilePic: String?
) {
    val mediaUrl: String?
        get() = _mediaUrl?.replace(":5000", "")

    val senderProfilePic: String?
        get() = _senderProfilePic?.replace(":5000", "")
}

data class SendMessageRequest(
    val chatId: Int,
    val type: String, // TEXT or IMAGE
    val content: String? = null,
    val messageImage: String? = null // base64 encoded image
)

package com.mustafafaraz.locateme.utils

import java.text.SimpleDateFormat
import java.util.*

object TimeFormatter {

    fun formatTimeAgo(timestamp: String): String {
        return try {
            // Parse the ISO 8601 timestamp from backend (e.g., "2025-12-07T08:30:00.000Z")
            val sdf = SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss", Locale.getDefault())
            sdf.timeZone = TimeZone.getTimeZone("UTC")
            val date = sdf.parse(timestamp.substringBefore("."))

            if (date != null) {
                val now = System.currentTimeMillis()
                val diff = now - date.time

                val seconds = diff / 1000
                val minutes = seconds / 60
                val hours = minutes / 60
                val days = hours / 24
                val weeks = days / 7
                val months = days / 30
                val years = days / 365

                when {
                    years > 0 -> "$years year${if (years > 1) "s" else ""} ago"
                    months > 0 -> "$months month${if (months > 1) "s" else ""} ago"
                    weeks > 0 -> "$weeks week${if (weeks > 1) "s" else ""} ago"
                    days > 0 -> "$days day${if (days > 1) "s" else ""} ago"
                    hours > 0 -> "$hours hour${if (hours > 1) "s" else ""} ago"
                    minutes > 0 -> "$minutes minute${if (minutes > 1) "s" else ""} ago"
                    else -> "Just now"
                }
            } else {
                timestamp.substringBefore("T")
            }
        } catch (e: Exception) {
            // Fallback: just show the date part
            timestamp.substringBefore("T")
        }
    }
}

package com.mustafafaraz.locateme.utils

import java.text.SimpleDateFormat
import java.util.*

object TimeFormatter {

    fun formatTimeAgo(timestamp: String): String {
        return try {
            // Parse the ISO 8601 timestamp from backend (e.g., "2025-12-07T08:30:00.000Z")
            val sdf = SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss", Locale.getDefault())
            sdf.timeZone = TimeZone.getTimeZone("UTC")
            val date = sdf.parse(timestamp.substringBefore("."))

            if (date != null) {
                val now = System.currentTimeMillis()
                val diff = now - date.time

                val seconds = diff / 1000
                val minutes = seconds / 60
                val hours = minutes / 60
                val days = hours / 24
                val weeks = days / 7
                val months = days / 30
                val years = days / 365

                when {
                    years > 0 -> "$years year${if (years > 1) "s" else ""} ago"
                    months > 0 -> "$months month${if (months > 1) "s" else ""} ago"
                    weeks > 0 -> "$weeks week${if (weeks > 1) "s" else ""} ago"
                    days > 0 -> "$days day${if (days > 1) "s" else ""} ago"
                    hours > 0 -> "$hours hour${if (hours > 1) "s" else ""} ago"
                    minutes > 0 -> "$minutes minute${if (minutes > 1) "s" else ""} ago"
                    else -> "Just now"
                }
            } else {
                timestamp.substringBefore("T")
            }
        } catch (e: Exception) {
            // Fallback: just show the date part
            timestamp.substringBefore("T")
        }
    }

    fun formatTime(timestamp: String): String {
        return try {
            // Parse the ISO 8601 timestamp from backend
            val sdf = SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss", Locale.getDefault())
            sdf.timeZone = TimeZone.getTimeZone("UTC")
            val date = sdf.parse(timestamp.substringBefore("."))

            if (date != null) {
                // Format to readable time (e.g., "10:30 AM")
                val outputFormat = SimpleDateFormat("hh:mm a", Locale.getDefault())
                outputFormat.timeZone = TimeZone.getDefault() // Convert to local time
                outputFormat.format(date)
            } else {
                timestamp.substringAfter("T").substringBefore(".")
            }
        } catch (e: Exception) {
            // Fallback: just show the time part
            timestamp.substringAfter("T").substringBefore(".")
        }
    }
}
